class Matrix:
    def __init__(self, matrix_string):
        # Parse the input string into a list of list of integers.
        # Split lines, then split each line on any whitespace to handle multiple spaces.
        self._matrix = [
            [int(num) for num in line.split()]
            for line in matrix_string.splitlines()
            if line.strip() != ""
        ]

    def row(self, index):
        # index is 1-based
        return list(self._matrix[index - 1])

    def column(self, index):
        # index is 1-based
        col_idx = index - 1
        return [row[col_idx] for row in self._matrix]
